solution:
enum TrafficLight {
  Red,
  Yellow,
  Green,
}

fn action(light: TrafficLight) -> Str {
  return match light {
    Red => "Stop",
    Yellow => "Slow down",
    Green => "Go",
  };
}

fn main() -> Int {
  io.println(action(Red));
  io.println(action(Yellow));
  io.println(action(Green));
  return 0;
}
